from pathlib import Path
p = Path('artifacts/frontend/src/components/video/VideoTimelineEditor.tsx')
s = p.read_text()

def r(a: str, b: str, count: int = 1) -> None:
    global s
    if a not in s:
        raise SystemExit('missing anchor: ' + a[:160])
    s = s.replace(a, b, count)

if 'Bloquear no Beat Sync' not in s:
    r('''      <div className="rounded-xl border bg-muted/30 p-3 text-xs text-muted-foreground"><p className="font-medium text-foreground">Corte individual</p><p className="mt-1">O arquivo original não é alterado. O editor usa apenas o trecho definido abaixo.</p></div>
      <RangeField label="Entrada"''', '''      <div className="rounded-xl border bg-muted/30 p-3 text-xs text-muted-foreground"><p className="font-medium text-foreground">Corte individual</p><p className="mt-1">O arquivo original não é alterado. O editor usa apenas o trecho definido abaixo.</p></div>
      <label className="flex items-center justify-between gap-3 rounded-xl border bg-background p-3 text-xs"><span><strong className="block">Bloquear no Beat Sync</strong><span className="text-[10px] text-muted-foreground">Mantém este clipe e suas bordas exatamente onde estão.</span></span><input type="checkbox" checked={selectedClip.beatLocked === true} onChange={(event) => updateClip({ beatLocked: event.target.checked })} className="accent-primary" /></label>
      <RangeField label="Entrada"''')

if 'clip.beatLocked ? " · 🔒"' not in s:
    r('{index + 1}. {clip.name}{(clip.transitionOut ?? "cut") !== "cut" ? ` · ${transitionLabel(clip.transitionOut)}` : ""}</span>', '{index + 1}. {clip.name}{clip.beatLocked ? " · 🔒" : ""}{(clip.transitionOut ?? "cut") !== "cut" ? ` · ${transitionLabel(clip.transitionOut)}` : ""}</span>')

if 'Intensidade do Beat Sync' not in s:
    anchor = '<button type="button" onClick={syncCutsToBeats} disabled={clips.length < 2} className="w-full rounded-lg bg-amber-600 px-3 py-2.5 text-xs font-semibold text-white disabled:opacity-40"><Scissors className="mr-1.5 inline h-3.5 w-3.5" />Sincronizar cortes com batidas</button>'
    replacement = '''<label className="block space-y-1"><span className="text-[10px] text-muted-foreground">Intensidade do Beat Sync</span><select value={beatSyncStrength} onChange={(event) => setBeatSyncStrength(event.target.value as BeatSyncStrength)} className="h-8 w-full rounded-lg border bg-background px-2 text-[11px]"><option value="light">Leve · ajustes discretos</option><option value="balanced">Equilibrado · recomendado</option><option value="aggressive">Agressivo · ritmo forte</option></select></label><label className="flex items-center justify-between gap-3 rounded-lg border bg-background px-2.5 py-2 text-[10px]"><span>Acentuar transições e elementos nos downbeats</span><input type="checkbox" checked={syncVisualAccents} onChange={(event) => setSyncVisualAccents(event.target.checked)} className="accent-primary" /></label><div className="space-y-2 rounded-lg border bg-background p-2.5"><div className="flex items-center justify-between gap-2"><div><p className="text-[10px] font-semibold">Marcadores manuais</p><p className="text-[9px] text-muted-foreground">Fixe momentos importantes que o Beat Sync deve considerar.</p></div><button type="button" onClick={addManualBeatMarker} className="rounded-md border px-2 py-1 text-[9px] font-medium">+ No cursor</button></div>{manualBeatMarkers.length > 0 && <div className="flex flex-wrap gap-1">{manualBeatMarkers.map((marker) => <button key={marker} type="button" onClick={() => setManualBeatMarkers((current) => current.filter((time) => time !== marker))} className="rounded-full border px-1.5 py-0.5 text-[9px] tabular-nums" title="Remover marcador">{timeLabel(marker)} ×</button>)}<button type="button" onClick={() => setManualBeatMarkers([])} className="rounded-full px-1.5 py-0.5 text-[9px] text-muted-foreground underline">limpar</button></div>}</div><div className="rounded-lg border bg-background p-2.5"><div className="flex items-center justify-between gap-2"><span className="text-[10px] font-semibold">Prévia antes de aplicar</span><span className="rounded-full bg-amber-500/10 px-2 py-0.5 text-[9px] font-semibold text-amber-700 dark:text-amber-300">{beatCutPreview.length} corte{beatCutPreview.length === 1 ? "" : "s"}</span></div>{beatCutPreview.length > 0 ? <div className="mt-2 space-y-1">{beatCutPreview.slice(0, 5).map((item) => <div key={`${item.clipId}-${item.target}`} className="flex items-center justify-between gap-2 text-[9px]"><span className="truncate">Corte {item.index + 1} → {item.index + 2}{item.manual ? " · manual" : item.downbeat ? " · downbeat" : ""}</span><span className="shrink-0 tabular-nums text-muted-foreground">{item.delta >= 0 ? "+" : ""}{Math.round(item.delta * 1000)} ms</span></div>)}{beatCutPreview.length > 5 && <p className="text-[9px] text-muted-foreground">+ {beatCutPreview.length - 5} ajustes adicionais</p>}</div> : <p className="mt-1 text-[9px] text-muted-foreground">Nenhum corte será movido com a configuração atual. Clipes bloqueados são ignorados.</p>}</div><button type="button" onClick={syncCutsToBeats} disabled={clips.length < 2 || beatCutPreview.length === 0} className="w-full rounded-lg bg-amber-600 px-3 py-2.5 text-xs font-semibold text-white disabled:opacity-40"><Scissors className="mr-1.5 inline h-3.5 w-3.5" />Aplicar Beat Sync{beatCutPreview.length ? ` · ${beatCutPreview.length}` : ""}</button>'''
    r(anchor, replacement)

if 'video-manual-' not in s:
    r('>{showBeatMarkers && activeBeatAnalysis && beatTimes.map((beat, index) => <span key={`video-beat-${beat.toFixed(3)}-${index}`}', '>{showBeatMarkers && manualBeatMarkers.map((marker) => <span key={`video-manual-${marker}`} className="pointer-events-none absolute inset-y-0 z-10 w-[2px] border-l border-dashed border-cyan-400" style={{ left: `${clamp(marker / projectDuration * 100, 0, 100)}%` }} />)}{showBeatMarkers && activeBeatAnalysis && beatTimes.map((beat, index) => <span key={`video-beat-${beat.toFixed(3)}-${index}`}')
    r('>{showBeatMarkers && activeBeatAnalysis && beatTimes.map((beat, index) => <span key={`audio-beat-${beat.toFixed(3)}-${index}`}', '>{showBeatMarkers && manualBeatMarkers.map((marker) => <span key={`audio-manual-${marker}`} className="pointer-events-none absolute inset-y-0 z-10 w-[2px] border-l border-dashed border-cyan-300" style={{ left: `${clamp(marker / projectDuration * 100, 0, 100)}%` }} />)}{showBeatMarkers && activeBeatAnalysis && beatTimes.map((beat, index) => <span key={`audio-beat-${beat.toFixed(3)}-${index}`}')

if 'downbeatTimes.some((time) => Math.abs(time - beat) < 0.025)' not in s:
    r('index % 4 === 0 ? "w-[2px]" : "w-px"', 'downbeatTimes.some((time) => Math.abs(time - beat) < 0.025) ? "w-[2px] opacity-100" : "w-px opacity-70"', 2)

p.write_text(s)
